-- Denmark deep-dive page translations: page fields, stats, cards, penalty rows, steps, portal.
-- Follows the real schema (049_tracker_deepdive_schema.sql, 052_section_intros.sql,
-- 057_lifecycle_penalty_schema.sql): translation rows join back to the English-language
-- base rows via country_id + section/sort_order, not a flat key-value table.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Mandato de capacidad técnica (no un mandato de transmisión)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El desarrollo de NemHandel BIS 4, las especificaciones de SAF-T 2.0 y la práctica de aplicación continúan evolucionando — confirme los requisitos actuales directamente con Erhvervsstyrelsen antes de construir una integración.', 'La Ley de Contabilidad danesa es inusual: exige la capacidad técnica para facturar electrónicamente, no que cada factura se envíe realmente de forma electrónica — y ya está en plena transición hacia un nuevo formato nacional.', 'Dinamarca está en pleno proceso de migración — el formato con el que construye hoy no es el formato que utilizará a finales de la década.', 'Lo más importante que hay que entender sobre Dinamarca: esta ley exige capacidad, no transmisión universal — una diferencia significativa con respecto a todos los países con modelo de compensación de este seguimiento.', 'El cumplimiento aquí depende del estado de su sistema de contabilidad, no de un único paso de "registro" — planifique en torno a las seis obligaciones legales.', 'Las multas danesas escalan drásticamente con la gravedad — y la sanción última va mucho más allá del dinero.' FROM countries WHERE name_en = 'Denmark';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Pflicht zur technischen Fähigkeit (keine Übermittlungspflicht)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Entwicklung von NemHandel BIS 4, die SAF-T-2.0-Spezifikationen und die Durchsetzungspraxis entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei Erhvervsstyrelsen, bevor Sie eine Integration aufbauen.', 'Das dänische Buchführungsgesetz ist ungewöhnlich: Es verlangt die technische Fähigkeit zur E-Rechnung, nicht dass tatsächlich jede Rechnung elektronisch versendet wird — und befindet sich bereits mitten im Übergang zu einem neuen nationalen Format.', 'Dänemark befindet sich mitten in der Migration — das Format, gegen das Sie heute entwickeln, ist nicht das Format, das Sie am Ende des Jahrzehnts verwenden werden.', 'Das mit Abstand Wichtigste, was man über Dänemark verstehen muss: Dieses Gesetz verlangt Fähigkeit, nicht universelle Übermittlung — ein bedeutsamer Unterschied zu jedem Clearing-Modell-Land in diesem Tracker.', 'Konformität hängt hier vom Status Ihres Buchführungssystems ab, nicht von einem einzelnen "Anmeldeschritt" — planen Sie rund um die sechs gesetzlichen Pflichten.', 'Dänische Bußgelder steigen mit der Schwere drastisch an — und die ultimative Sanktion geht weit über Geld hinaus.' FROM countries WHERE name_en = 'Denmark';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Obligation de capacité technique (pas une obligation de transmission)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le développement de NemHandel BIS 4, les spécifications SAF-T 2.0 et la pratique en matière d''application continuent d''évoluer — confirmez les exigences actuelles directement auprès d''Erhvervsstyrelsen avant de construire une intégration.', 'La loi danoise sur la comptabilité est inhabituelle : elle impose la capacité technique de facturer électroniquement, et non que chaque facture soit réellement envoyée électroniquement — et elle est déjà en pleine transition vers un nouveau format national.', 'Le Danemark est en pleine migration — le format sur lequel vous développez aujourd''hui n''est pas celui que vous utiliserez d''ici la fin de la décennie.', 'L''élément le plus important à comprendre sur le Danemark : cette loi impose une capacité, pas une transmission universelle — une différence significative par rapport à tous les pays à modèle de contrôle de ce suivi.', 'Ici, la conformité dépend du statut de votre système de comptabilité, et non d''une simple étape d''« inscription » — organisez-vous autour des six obligations légales.', 'Les amendes danoises augmentent fortement avec la gravité — et la sanction ultime va bien au-delà de l''argent.' FROM countries WHERE name_en = 'Denmark';

