INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formatos actuales', '[["Formato nacional", "OIOUBL 2.1"], ["Formato internacional", "Peppol BIS 3.0 (conforme con EN 16931)"], ["OIOUBL 3.0", "Cancelado, enero de 2026 — sin sustituto"]]', 'Ambos formatos vigentes deben ser compatibles con cualquier sistema que aspire al estado "registrado" — se trata de un requisito de contratación no negociable, no de una elección entre uno u otro.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Aktuelle Formate', '[["Nationales Format", "OIOUBL 2.1"], ["Internationales Format", "Peppol BIS 3.0 (EN-16931-konform)"], ["OIOUBL 3.0", "Gestrichen, Januar 2026 — kein Ersatz"]]', 'Beide geltenden Formate müssen von jedem System unterstützt werden, das den Status "registriert" anstrebt — das ist ein nicht verhandelbarer Punkt bei der Beschaffung, keine Entweder-oder-Wahl.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Formats actuels', '[["Format national", "OIOUBL 2.1"], ["Format international", "Peppol BIS 3.0 (conforme à l''EN 16931)"], ["OIOUBL 3.0", "Annulé, janvier 2026 — aucun remplacement"]]', 'Les deux formats en vigueur doivent être pris en charge par tout système visant le statut « enregistré » — c''est un point non négociable de la liste de contrôle des achats, pas un choix entre l''un ou l''autre.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'La ruta de migración', '[["Formato de destino", "Nemhandel BIS 4 (Peppol BIS 4 localizado)"], ["Depende de", "El desarrollo del propio Peppol BIS 4, que incorpora PINT"], ["Impulsor normativo", "Plazo transfronterizo del ViDA de la UE, 1 de julio de 2030"]]', 'Una vez completada la migración, Erhvervsstyrelsen propone simplificar el requisito de formato de la Ley de Contabilidad a un único estándar admitido — solo el soporte de Nemhandel BIS.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Der Migrationspfad', '[["Zielformat", "Nemhandel BIS 4 (lokalisiertes Peppol BIS 4)"], ["Abhängig von", "Der Entwicklung von Peppol BIS 4 selbst, einschließlich PINT"], ["Regulatorischer Treiber", "EU-ViDA-Frist für grenzüberschreitende Transaktionen, 1. Juli 2030"]]', 'Nach Abschluss der Migration schlägt Erhvervsstyrelsen vor, die Formatanforderung des Buchführungsgesetzes auf einen einzigen unterstützten Standard zu vereinfachen — allein die Unterstützung von Nemhandel BIS.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'La trajectoire de migration', '[["Format de destination", "Nemhandel BIS 4 (Peppol BIS 4 localisé)"], ["Dépend de", "Le développement de Peppol BIS 4 lui-même, intégrant PINT"], ["Moteur réglementaire", "Échéance transfrontalière ViDA de l''UE, 1er juillet 2030"]]', 'Une fois la migration achevée, Erhvervsstyrelsen propose de simplifier l''exigence de format de la loi sur la comptabilité à une seule norme prise en charge — le seul support Nemhandel BIS.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Requisitos específicos de Dinamarca', '[["Plan de cuentas", "Standardkontoplan (estructura estándar danesa)"], ["Reporte de auditoría", "SAF-T danés, generado a petición desde enero de 2027"], ["División del rastro de auditoría", "Kontrolspor (rastro de control) frente a transaktionsspor (rastro de transacciones)"]]', 'Un libro mayor configurado de forma global no se corresponde de forma nativa con el standardkontoplan danés — se trata de una tarea de localización genuina, no solo de un ejercicio de conversión de formato.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Dänemarkspezifische Anforderungen', '[["Kontenplan", "Standardkontoplan (dänische Standardstruktur)"], ["Prüfungsbericht", "Dänisches SAF-T, ab Januar 2027 auf Anfrage erzeugt"], ["Aufteilung des Prüfpfads", "Kontrolspor (Kontrollspur) vs. transaktionsspor (Transaktionsspur)"]]', 'Ein global konfiguriertes Hauptbuch bildet den dänischen Standardkontoplan nicht nativ ab — das ist eine echte Lokalisierungsaufgabe, keine reine Formatumwandlung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Exigences propres au Danemark', '[["Plan comptable", "Standardkontoplan (structure standard danoise)"], ["Déclaration d''audit", "SAF-T danois, généré sur demande à partir de janvier 2027"], ["Séparation de la piste d''audit", "Kontrolspor (piste de contrôle) vs. transaktionsspor (piste de transaction)"]]', 'Un grand livre configuré de manière globale ne correspond pas nativement au standardkontoplan danois — il s''agit d''une véritable tâche de localisation, pas d''un simple exercice de conversion de format.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Archivo', '[["Conservación estándar", "5 años (la mayoría de los casos)"], ["Requisito de acceso", "Debe admitir solicitudes de datos de la autoridad a petición"]]', 'Compruébelo explícitamente: simule una solicitud de datos de Erhvervsstyrelsen o Skattestyrelsen antes de que se lo pidan de verdad — es una de las seis obligaciones principales bajo la Ley.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Archivierung', '[["Standardaufbewahrung", "5 Jahre (in den meisten Fällen)"], ["Zugriffsanforderung", "Muss behördliche Datenanfragen auf Anfrage unterstützen"]]', 'Testen Sie dies ausdrücklich: Simulieren Sie eine Datenanfrage von Erhvervsstyrelsen oder Skattestyrelsen, bevor Sie tatsächlich danach gefragt werden — es ist eine der sechs Hauptpflichten nach dem Gesetz.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Archivage', '[["Conservation standard", "5 ans (la plupart des cas)"], ["Exigence d''accès", "Doit prendre en charge les demandes de données de l''administration sur demande"]]', 'Testez cela explicitement : simulez une demande de données d''Erhvervsstyrelsen ou de Skattestyrelsen avant qu''on ne vous la demande réellement — c''est l''une des six obligations principales prévues par la loi.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Lo que la ley realmente exige', '[["Tipo de mandato", "Capacidad técnica de enviar/recibir"], ["No se exige", "Transmisión universal de facturas electrónicas para cada transacción"]]', 'Una empresa puede ser plenamente conforme aunque siga intercambiando algunas facturas de otras formas — lo que no puede hacer es carecer por completo de la capacidad, o usar un sistema no conforme para registrar su contabilidad.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was das Gesetz tatsächlich verlangt', '[["Art der Vorgabe", "Technische Fähigkeit zum Senden/Empfangen"], ["Nicht erforderlich", "Universelle E-Rechnungsübermittlung für jede Transaktion"]]', 'Ein Unternehmen kann vollständig konform sein, während es weiterhin manche Rechnungen auf andere Weise austauscht — was es nicht darf, ist die Fähigkeit vollständig zu fehlen oder ein nicht konformes System zur Buchführung zu nutzen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce que la loi exige réellement', '[["Type d''obligation", "Capacité technique d''envoi/réception"], ["Non requis", "Transmission universelle de factures électroniques pour chaque transaction"]]', 'Une entreprise peut être pleinement conforme tout en continuant à échanger certaines factures autrement — ce qu''elle ne peut pas faire, c''est ne pas du tout avoir la capacité, ou utiliser un système non conforme pour tenir sa comptabilité.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'NemHandel', '[["Acceso", "Solo empresas danesas con número CVR"], ["Empresas extranjeras", "Utilizan en su lugar un Punto de Acceso Peppol"], ["Directorio", "NemHandelsregisteret (registro público)"]]', 'NemHandel es la plataforma nacional de Dinamarca, pero está interconectada con la red Peppol más amplia — no necesita un número CVR para participar, solo un punto de entrada diferente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'NemHandel', '[["Zugang", "Nur dänische Unternehmen mit CVR-Nummer"], ["Ausländische Unternehmen", "Nutzen stattdessen einen Peppol Access Point"], ["Verzeichnis", "NemHandelsregisteret (öffentliches Register)"]]', 'NemHandel ist Dänemarks nationale Plattform, aber sie ist mit dem breiteren Peppol-Netzwerk verbunden — Sie benötigen keine CVR-Nummer zur Teilnahme, nur einen anderen Einstiegspunkt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'NemHandel', '[["Accès", "Entreprises danoises disposant d''un numéro CVR uniquement"], ["Entreprises étrangères", "Utilisent un Access Point Peppol à la place"], ["Annuaire", "NemHandelsregisteret (registre public)"]]', 'NemHandel est la plateforme nationale du Danemark, mais elle est interconnectée avec le réseau Peppol plus large — vous n''avez pas besoin d''un numéro CVR pour y participer, seulement d''un point d''entrée différent.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Dos vías hacia la conformidad del sistema', '[["Vía A", "Sistema certificado en la lista registrada de Erhvervsstyrelsen"], ["Vía B", "Sistema personalizado no registrado, declarado a la Autoridad"]]', 'Personalizado" no significa "menos supervisado" — la Vía B debe igualmente cumplir todos los requisitos técnicos legales, significa que usted asume la carga de demostrar el cumplimiento en lugar de depender de un proveedor precertificado.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Zwei Wege zur Systemkonformität', '[["Weg A", "Zertifiziertes System auf der registrierten Liste von Erhvervsstyrelsen"], ["Weg B", "Nicht registriertes individuelles System, bei der Behörde gemeldet"]]', 'Individuell" bedeutet nicht "weniger geprüft" — Weg B muss jede gesetzliche technische Anforderung dennoch erfüllen, es bedeutet, dass Sie selbst die Beweislast für die Konformität tragen, statt sich auf einen vorzertifizierten Anbieter zu verlassen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Deux voies vers la conformité du système', '[["Voie A", "Système certifié sur la liste enregistrée d''Erhvervsstyrelsen"], ["Voie B", "Système personnalisé non enregistré, déclaré à l''administration"]]', '« Personnalisé » ne signifie pas « moins contrôlé » — la voie B doit tout de même satisfaire chaque exigence technique légale, cela signifie que vous portez vous-même la charge de prouver la conformité plutôt que de vous appuyer sur un fournisseur préqualifié.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'NemHandel por defecto (desde julio de 2026)', '[["Mecanismo", "Inscripción automática para entidades con sistemas registrados"], ["Exclusión voluntaria", "Se ofrece una ventana, no participación obligatoria"]]', 'Esta campaña impulsa la emisión real de facturas electrónicas sin cambiar el mandato legal subyacente — decida deliberadamente si excluirse en lugar de dejar que la inscripción por defecto le sorprenda sin preparación.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'NemHandel standardmäßig (ab Juli 2026)', '[["Mechanismus", "Automatische Anmeldung für Einrichtungen mit registrierten Systemen"], ["Opt-out", "Fenster vorhanden, keine Pflichtteilnahme"]]', 'Diese Kampagne fördert die tatsächliche Ausstellung von E-Rechnungen, ohne die zugrunde liegende gesetzliche Vorgabe zu ändern — entscheiden Sie bewusst, ob Sie sich abmelden, statt sich von der Standardanmeldung unvorbereitet überraschen zu lassen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'NemHandel par défaut (à partir de juillet 2026)', '[["Mécanisme", "Inscription automatique pour les entités disposant de systèmes enregistrés"], ["Désinscription", "Une fenêtre est proposée, la participation n''est pas obligatoire"]]', 'Cette campagne encourage l''émission réelle de factures électroniques sans modifier l''obligation légale sous-jacente — décidez délibérément de vous désinscrire ou non plutôt que de laisser l''inscription par défaut vous prendre au dépourvu.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚠️ Más allá de las multas: disolución forzosa', NULL, NULL, 'En los casos más graves, las consecuencias van más allá de las sanciones económicas hasta llegar a la disolución forzosa de la entidad — se trata de una categoría de riesgo genuinamente existencial, no solo de un coste de hacer negocios.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚠️ Über Bußgelder hinaus: Zwangsauflösung', NULL, NULL, 'In den schwersten Fällen reichen die Folgen über finanzielle Sanktionen hinaus bis zur Zwangsauflösung des Unternehmens — dies ist eine wirklich existenzielle Risikokategorie, nicht nur ein Geschäftskostenfaktor.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚠️ Au-delà des amendes : dissolution forcée', NULL, NULL, 'Dans les cas les plus graves, les conséquences vont au-delà des sanctions financières jusqu''à la dissolution forcée de l''entité — il s''agit d''une catégorie de risque véritablement existentielle, pas simplement d''un coût lié à l''activité.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📋 Incumplimiento B2G', NULL, NULL, 'Aparte de las sanciones generales de la Ley de Contabilidad, el incumplimiento de las normas de facturación al sector público puede generar multas de la Autoridad Empresarial Danesa específicamente vinculadas a esa relación.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 B2G-Nichteinhaltung', NULL, NULL, 'Getrennt von den allgemeinen Bußgeldern nach dem Buchführungsgesetz kann die Nichtbeachtung der Regeln für die Rechnungsstellung an den öffentlichen Sektor Bußgelder der dänischen Unternehmensbehörde auslösen, die speziell an diese Beziehung geknüpft sind.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 Non-conformité B2G', NULL, NULL, 'Indépendamment des sanctions générales prévues par la loi sur la comptabilité, le non-respect des règles de facturation au secteur public peut entraîner des amendes de l''Autorité danoise des entreprises spécifiquement liées à cette relation.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔄 La cancelación de OIOUBL 3.0 importa aquí', NULL, NULL, 'Dado que se canceló el formato sucesor previsto, cualquier hoja de ruta de cumplimiento construida en torno a él necesita replanificarse en torno al calendario de Nemhandel BIS 4 en su lugar — un riesgo de planificación real, no hipotético.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔄 Die Streichung von OIOUBL 3.0 spielt hier eine Rolle', NULL, NULL, 'Da das geplante Nachfolgeformat gestrichen wurde, muss jede darauf aufgebaute Compliance-Roadmap stattdessen um den Zeitplan von Nemhandel BIS 4 herum neu geplant werden — ein reales, kein hypothetisches Planungsrisiko.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔄 L''annulation d''OIOUBL 3.0 a son importance ici', NULL, NULL, 'Le format successeur prévu ayant été abandonné, toute feuille de route de conformité bâtie autour de lui doit être replanifiée autour du calendrier de Nemhandel BIS 4 à la place — un risque de planification réel, et non hypothétique.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Denmark' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'es', 'Rango de multa legal', '10.000 – 1.500.000 DKK (~1.350 € – 200.000 €)', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'Denmark' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'de', 'Gesetzliche Bußgeldspanne', '10.000 – 1.500.000 DKK (~1.350 € – 200.000 €)', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'Denmark' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'fr', 'Fourchette d''amende légale', '10 000 – 1 500 000 DKK (~1 350 € – 200 000 €)', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'Denmark' AND dpr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'es', 'La gravedad depende de', 'La naturaleza y duración de la infracción, y si se trata de un patrón reiterado', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'Denmark' AND dpr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'de', 'Die Schwere hängt ab von', 'Art und Dauer des Verstoßes sowie davon, ob ein wiederholtes Muster vorliegt', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'Denmark' AND dpr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'fr', 'La gravité dépend de', 'La nature et la durée de l''infraction, et s''il s''agit d''un schéma répété', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'Denmark' AND dpr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Decida: sistema registrado o sistema personalizado declarado', 'Consulte primero el registro oficial de Erhvervsstyrelsen — utilizar un sistema ya certificado supone considerablemente menos trabajo que declarar y demostrar el cumplimiento de una construcción personalizada.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Entscheiden Sie: registriertes System oder gemeldetes individuelles System', 'Prüfen Sie zunächst das offizielle Register von Erhvervsstyrelsen — die Nutzung eines bereits zertifizierten Systems ist deutlich weniger Aufwand als die Meldung und der Nachweis der Konformität für eine individuelle Lösung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Décidez : système enregistré ou système personnalisé déclaré', 'Consultez d''abord le registre officiel d''Erhvervsstyrelsen — utiliser un système déjà certifié représente nettement moins de travail que de déclarer et de prouver la conformité d''une solution personnalisée.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme la compatibilidad con ambos formatos: OIOUBL 2.1 y Peppol BIS 3.0', 'Ambos son necesarios hoy para el estado registrado — considérelo no negociable al evaluar o cambiar de sistema.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie die Unterstützung beider Formate: OIOUBL 2.1 und Peppol BIS 3.0', 'Beide sind heute für den registrierten Status erforderlich — behandeln Sie dies bei der Bewertung oder dem Wechsel von Systemen als nicht verhandelbar.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez la prise en charge des deux formats : OIOUBL 2.1 et Peppol BIS 3.0', 'Les deux sont aujourd''hui requis pour le statut enregistré — considérez cela comme non négociable lors de l''évaluation ou du changement de système.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Regístrese en NemHandel si dispone de un número CVR', 'Las empresas extranjeras sin CVR deben configurar en su lugar una conexión de Punto de Acceso Peppol para recibir y enviar facturas OIOUBL/Peppol.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie sich bei NemHandel, wenn Sie eine CVR-Nummer besitzen', 'Ausländische Unternehmen ohne CVR sollten stattdessen eine Peppol-Access-Point-Verbindung einrichten, um OIOUBL-/Peppol-Rechnungen zu empfangen und zu senden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Inscrivez-vous à NemHandel si vous détenez un numéro CVR', 'Les entreprises étrangères sans CVR doivent plutôt mettre en place une connexion à un Access Point Peppol pour recevoir et envoyer des factures OIOUBL/Peppol.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Adapte su libro mayor al standardkontoplan danés', 'No dé por sentado que un plan de cuentas configurado globalmente satisface esto — es un requisito de localización genuino para el estado de sistema registrado.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bilden Sie Ihr Hauptbuch auf den dänischen Standardkontoplan ab', 'Gehen Sie nicht davon aus, dass ein global konfigurierter Kontenplan dies erfüllt — es ist eine echte Lokalisierungsanforderung für den Status als registriertes System.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Faites correspondre votre grand livre au standardkontoplan danois', 'Ne présumez pas qu''un plan comptable configuré globalement suffit — il s''agit d''une véritable exigence de localisation pour le statut de système enregistré.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Decida su postura ante NemHandel por defecto antes de julio de 2026', 'Si su sistema está registrado, se le inscribirá automáticamente — decida activamente si permanecer o excluirse en lugar de dejar que ocurra de forma pasiva.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Legen Sie Ihre Haltung zu NemHandel standardmäßig vor Juli 2026 fest', 'Ist Ihr System registriert, werden Sie automatisch angemeldet — entscheiden Sie aktiv, ob Sie dabei bleiben oder sich abmelden, statt es passiv geschehen zu lassen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Décidez de votre position vis-à-vis de NemHandel par défaut avant juillet 2026', 'Si votre système est enregistré, vous serez inscrit automatiquement — décidez activement de rester ou de vous désinscrire plutôt que de laisser faire passivement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepare la generación del SAF-T danés antes de enero de 2027', 'Confirme que su sistema puede producir SAF-T 2.0 a petición, y que sus rastros de auditoría kontrolspor y transaktionsspor están correctamente diferenciados.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie die Erzeugung des dänischen SAF-T vor Januar 2027 vor', 'Bestätigen Sie, dass Ihr System SAF-T 2.0 auf Anfrage erzeugen kann und dass Ihre Prüfpfade kontrolspor und transaktionsspor ordnungsgemäß unterschieden werden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez la génération du SAF-T danois avant janvier 2027', 'Vérifiez que votre système peut produire le SAF-T 2.0 sur demande, et que vos pistes d''audit kontrolspor et transaktionsspor sont correctement distinguées.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Siga la migración de OIOUBL a NemHandel BIS 4', 'No construya integraciones a largo plazo sobre OIOUBL 3.0 — está cancelado. Esté atento en su lugar al candidato de lanzamiento de NemHandel BIS 4 de 2027–2028.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verfolgen Sie die Migration von OIOUBL zu NemHandel BIS 4', 'Bauen Sie keine langfristigen Integrationen auf OIOUBL 3.0 auf — es ist gestrichen. Achten Sie stattdessen auf den Release Candidate von NemHandel BIS 4 in 2027–2028.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Suivez la migration d''OIOUBL vers NemHandel BIS 4', 'Ne construisez pas d''intégrations à long terme sur OIOUBL 3.0 — il est annulé. Surveillez plutôt le candidat de version 2027-2028 de NemHandel BIS 4.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Denmark' AND ds.sort_order = 6;

